<?php
namespace App\Http\Controllers; use App\Domain\Admin\Services\AuditService; use App\Domain\Marketing\Models\Discount; use Illuminate\Http\Request; use Illuminate\Validation\Rule; use Inertia\Inertia; class AdminDiscountsController {public function __construct(private AuditService $audit){} public function index(){return Inertia::render('Admin/Discounts/Index',['discounts'=>Discount::latest()->get()]);} public function store(Request $r){$d=$r->validate(['code'=>'required|string|max:50|unique:discounts,code','name'=>'required|string|max:120','type'=>['required',Rule::in(['percentage','fixed'])],'value'=>'required|integer|min:1','minimum_order_amount'=>'nullable|integer|min:0','usage_limit'=>'nullable|integer|min:1','per_customer_limit'=>'nullable|integer|min:1','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after:starts_at','active'=>'boolean']);$d['code']=strtoupper($d['code']);if($d['type']==='percentage'&&$d['value']>100)abort(422,'Percentage cannot exceed 100.');$m=Discount::create($d);$this->audit->record($r,'discount.created',$m,null,$m->toArray());return back()->with('success','Discount created.');} public function toggle(Request $r,Discount $discount){$before=$discount->toArray();$discount->update(['active'=>!$discount->active]);$this->audit->record($r,'discount.toggled',$discount,$before,$discount->fresh()->toArray());return back();}}
